import {start as startCngSession} from './characters/cng/campaign.js';
import { showAreaPicker } from './shared/map/layout.js';
import { start as startBusMission } from './characters/bus/campaign.js';
import { start as startRickshawMission } from './characters/rickshaw/campaign.js';
import { start as startBikerMission } from './characters/biker/campaign.js';
import { start as startShopMission } from './characters/shop/campaign.js';
import { createMainMenu } from './main-menu.js';
import { startStallGame } from './characters/stall/standalone-game.js';
const $=s=>document.querySelector(s);
let saved={};try{saved=JSON.parse(localStorage.getItem('dhaka-welcome')||'{}')}catch{}
let lang=saved.lang==='bn'?'bn':'en', sound=false;
const words={welcome:['WELCOME','স্বাগতম'],about:['ABOUT GAME','গেম সম্পর্কে'],dhakaTerror:['DHAKA TERROR','ঢাকা টেরর'],profile:['Profile','প্রোফাইল'],how:['How to play','খেলার নিয়ম'],loading:['Finding a little space in the traffic…','জ্যামের মাঝে একটু জায়গা খুঁজছি…'],eyebrow:['WHERE EVERY TURN IS A NEW DISASTER.','প্রতি মোড়ে নতুন বিপদ!'],description:['One city. Countless characters. Endless jhamela.\nDrive the streets, run the stalls, and survive the beautiful madness of Dhaka.','এক শহর। অগণিত চরিত্র। ঝামেলার শেষ নেই!\nরাস্তায় গাড়ি চালাও, স্টল সামলাও, আর ঢাকার এই পাগলাটে শহরে টিকে থাকো!'],choose:['START GAME','গেম শুরু করুন'],meet:['Meet the madness','ঢাকার গল্প জানুন'],free:['Free to explore','সবার জন্য উন্মুক্ত'],local:['Made for our streets','আমাদের রাস্তার গল্প'],street:['EVERY STREET HAS A STORY. YOURS STARTS HERE ↙','প্রতিটি রাস্তার একটি গল্প আছে। আপনার গল্প এখানে শুরু হয়!'],prototype:['BUS MISSION 01 / v0.2','বাস মিশন ০১ / v0.2'],copyright:['Copyright © 2026 POV Bangladesh | All rights reserved.','কপিরাইট © ২০২৬ পিএইচওভি বাংলাদেশ | সকল অধিকার রাখিত।'],replay:['Replay intro ↻','শুরুর পর্দা আবার দেখুন ↻'],footer:['Fictional chaos. Real love for Dhaka.','কাল্পনিক বিশৃঙ্খলা। ঢাকার জন্য সত্যিকারের ভালোবাসা।'],characters:['Characters','চরিত্র'],selectHint:['Your story is waiting. Choose a character above.','আপনার গল্প অপেক্ষা করছে। উপরে থেকে চরিত্র বাছাই।'],step:['01 / PICK YOUR PERSPECTIVE','০১ / আপনার দৃষ্টিভঙ্গি বাছাই'],who:['Who are you in this city?','আপনি এই শহরে কে?'],roleHint:['Same streets. Different stories.\nPick a character to discover their rules.','একই রাস্তা। ভিন্ন গল্প।\nনিয়ম জানতে চরিত্র বাছাই।'],rules:['View character rules','চরিত্রের নিয়ম দেখুন']};
const roles=[
{id:'bus',name:['Bus driver','বাস ড্রাইভার'],sub:['You drive. Your helper handles the gate.','আপনি চালান, হেলপার গেট সামলাবেন।'],tag:['DRIVER + HELPER','ড্রাইভার + হেলপার'],color:'#514537',accent:'#d6a456',quote:['“Pichhone jayga ase!”','“পিছনে জায়গা আছে!”'],rules:[['Drive the bus and stop at marked bays. Your capped helper works at the gate and boards passengers while you are parked.','বাস চালান ও চিহ্নিত স্টপে থামুন। টুপি পরা হেলপার গেটে থাকবেন এবং দাঁড়ানো বাসে যাত্রী তুলবেন।'],['Choose only your starting area. Drive freely with your helper through the shared Mirpur–Agargaon city.','শুধু শুরুর এলাকা বেছে নিন। হেলপারকে সঙ্গে নিয়ে মিরপুর–আগারগাঁও শহরে নিজেন মতো চালান।'],['Safe stops and clever crowd management earn respect. Hitting a pedestrian fails the mission.','নিরাপদ স্টপ ও বুদ্ধিদীপ্ত ব্যবস্থাপনায় সম্মান বাড়ে। পথচারীকে ধাক্কা দিলে মিশন ব্যর্থ।']]},
{id:'cng',name:['CNG driver','সিএনজি চালক'],sub:['Every destination is a debate.','গন্তব্য নিয়ে একটু আলোচনা হোক।'],tag:['THE NEGOTIATOR','দরদামের ওস্তাদ'],color:'#2a4a41',accent:'#8cba83',quote:['“Oi dike jamu na, mama!”','“ওই দিকে যামু না, মামা!”'],rules:[['Check the destination, agree on a fair fare, then accept your passenger.','গন্তব্য জানুন, ন্যায়সঙ্গত ভাড়া ঠিক করুন, তারপর যাত্রী নিন।'],['Choose a legal route and turn only where permitted. Watch the refusal meter.','বৈধ রুট বাছাই ও অনুমোদিত স্থানে মোড় নিন। প্রত্যাখ্যানের মিটারে নজর রাখুন।'],['Resolve fare disputes calmly. Clear roads and safe arrivals earn skill points.','শান্তভাবে ভাড়ার বিরোধ মেটান। পথ খোলা রাখা ও নিরাপদে পৌঁছানোয় দক্ষতা বাড়ে।']]},
{id:'rickshaw',name:['Rickshaw puller','রিকশাচালক'],sub:['Small lanes. Big ambitions.','ছোট গলি, বড় স্বপ্ন।'],tag:['THE LANE LEGEND','গলির ওস্তাদ'],color:'#3f4146',accent:'#d1a3a5',quote:['“Mama, shortcut chini!”','“মামা, শর্টকাট চিনি!”'],rules:[['Balance pedaling and stamina. Save some energy for the next lane.','প্যাডেল ও শক্তির ভারসাম্য রাখুন। পরের গলিতে শক্তি বাঁচান।'],['Use the bell thoughtfully and follow the direction of the road.','প্রয়োজনে বেল বাজান ও রাস্তার সঠিক দিকে চলুন।'],['Find a safe route through narrow lanes. Protect your passengers and give pedestrians room.','সরু গলিতে নিরাপদ পথ খুঁজুন। যাত্রীকে সুরক্ষিত রাখুন ও পথচারীকে জায়গা দিন।']]},
{id:'biker',name:['Biker','বাইকার'],sub:['Delivery time. Decision time.','ডেলিভারির তাড়া, সিদ্ধান্তের পালা।'],tag:['THE QUICK THINKER','দ্রুত সিদ্ধান্তের ওস্তাদ'],color:'#424543',accent:'#d5aa77',quote:['“Bhai, ektu side!”','“ভাই, একটু সাইড!”'],rules:[['Wear your helmet, collect the parcel, and check the delivery route.','হেলমেট পরুন, পার্সেল নিন ও ডেলিভারির রুট দেখুন।'],['Stay in the road lanes and obey signals. The footpath is for pedestrians.','রাস্তার লেনে থাকুন ও সিগন্যাল মানুন। ফুটপাত পথচারীদের জন্য।'],['Deliver carefully around traffic and hazards. Dangerous shortcuts reset the run.','যানবাহন ও বাধা এড়িয়ে সাবধানে পৌঁছান। বিপজ্জনক শর্টকাটে আবার শুরু করতে হবে।']]},
{id:'shop',name:['Footpath shopkeeper','ফুটপাতের দোকানদার'],sub:['Big business. Little space.','ছোট জায়গা, বড় ব্যবসা।'],tag:['THE SPACE STRATEGIST','জায়গা সামলানোর ওস্তাদ'],color:'#4b3b35',accent:'#cf9574',quote:['“Dokan na, public service!”','“দোকান না, পাবলিক সার্ভিস!”'],rules:[['Arrange your stall inside the marked area. Keep a clear walking path.','চিহ্নিত জায়গায় দোকান সাজান। হাঁটার পথ খোলা রাখুন।'],['Serve customers and manage the queue without blocking the footpath.','ফুটপাত না আটকে ক্রেতাদের সেবা দিন ও সারি সামলান।'],['Adapt your layout as the crowd changes. Clearing obstructions earns respect.','ভিড় অনুযায়ী দোকানের বিন্যাস বদলান। বাধা সরালে সম্মান বাড়ে।']]}];
const t=v=>v[lang==='bn'?1:0];
const svg=(body,view='0 0 240 150')=>`<svg viewBox="${view}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
const wheel=(x,y,r=14)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#142124" stroke="#839185" stroke-width="3"/><circle cx="${x}" cy="${y}" r="${r*.35}" fill="#d2c398"/>`;
function art(id){let b='';const ground='<ellipse cx="120" cy="132" rx="87" ry="7" fill="#101b1d55"/>';
if(id==='bus')b=`<path d="M28 64Q28 45 46 45H188Q207 45 210 66L216 115H27Z" fill="#d1a45b" stroke="#1a2a29" stroke-width="3"/><path d="M32 88H211V109H30Z" fill="#8d4940"/><path d="M39 54H71V81H39ZM79 54H111V81H79ZM119 54H151V81H119ZM160 54H190L198 81H160Z" fill="#294345" stroke="#a8b6a0" stroke-width="2"/><path d="M174 86H197V116H174Z" fill="#273936"/><path d="M45 95H153" stroke="#f5cf7f" stroke-width="3"/>${wheel(61,117)}${wheel(181,117)}<text x="89" y="40" fill="#ead1a0" font-size="10">ঢাকা পরিবহন</text><path d="M151 97L143 122M151 97L160 121L151 81V100M151 87L168 76" stroke="#d1b599" stroke-width="6" stroke-linecap="round"/><circle cx="151" cy="73" r="9" fill="#be9470"/><path d="M141 70Q151 57 160 70" fill="#172a29"/>`;
if(id==='cng')b=`<path d="M58 79L74 48Q117 33 163 49L188 94V119H49V99Z" fill="#689975" stroke="#1a302a" stroke-width="3"/><path d="M76 51Q117 40 159 52L168 80H67Z" fill="#1e3736" stroke="#b7b994" stroke-width="3"/><path d="M71 83H170V112H71Z" fill="#7ca27a"/><path d="M137 83V112M76 91H117" stroke="#28473d" stroke-width="3"/><path d="M161 52L146 80H169" fill="#b9c9aa"/><path d="M57 96H68V104H53M176 96H186V104H176" fill="#f3cd73"/>${wheel(76,119)}${wheel(167,119)}<path d="M83 46Q119 31 155 47" stroke="#e4c976" stroke-width="4" fill="none"/><text x="94" y="103" fill="#244737" font-size="9">মামার CNG</text>`;
if(id==='rickshaw')b=`${wheel(66,116,22)}${wheel(179,116,22)}<path d="M66 116L100 88L124 116H66L88 72M100 88H139L157 112H179L159 74" fill="none" stroke="#d1b16b" stroke-width="4"/><path d="M123 91V65Q121 26 155 30Q190 29 191 66V96Z" fill="#984f55" stroke="#d0ac8b" stroke-width="3"/><path d="M133 67Q132 42 156 42Q179 42 180 67Z" fill="#2c4742"/><path d="M128 85H184V101H128Z" fill="#cfb16e"/><path d="M144 87L155 74L168 87L155 97Z" fill="#768e6a"/><circle cx="100" cy="57" r="9" fill="#c49e7f"/><path d="M101 68L112 86L90 100L85 115M110 84L123 72" fill="none" stroke="#9cad99" stroke-width="7" stroke-linecap="round"/><path d="M93 51Q101 43 110 54" fill="#ded0a4"/>`;
if(id==='biker')b=`${wheel(64,117,22)}${wheel(177,117,22)}<path d="M64 117L99 87L137 117H64M177 117L152 77H134" fill="none" stroke="#ba9c6b" stroke-width="5"/><path d="M81 94L118 91L141 104L156 90L134 80H105Z" fill="#b27652" stroke="#172e2b" stroke-width="3"/><path d="M121 62L132 82L153 77M121 65L111 88L128 112" fill="none" stroke="#aab6a5" stroke-width="9" stroke-linecap="round"/><path d="M108 61L126 57L137 76L117 82Z" fill="#d2ad6d"/><circle cx="116" cy="46" r="13" fill="#bda77c"/><path d="M104 46Q100 27 118 28Q134 29 132 46Z" fill="#243d3d"/><path d="M118 38H132V45H118Z" fill="#97afac"/><rect x="49" y="65" width="37" height="30" rx="3" fill="#c8a67a"/><path d="M67 66V94M50 76H85" stroke="#84684e" stroke-width="2"/>`;
if(id==='shop')b=`<path d="M61 61V127M181 61V127" stroke="#b69e76" stroke-width="5"/><path d="M45 62L65 33H179L199 62Z" fill="#a85946"/><path d="M75 33L64 62H90L95 33M120 33V62H145L141 33M165 33L178 62H198L179 33" fill="#d3b67a"/><path d="M45 62Q55 78 65 62Q77 78 90 62Q104 78 119 62Q133 78 146 62Q162 78 178 62Q190 78 199 62" fill="#a85946"/><rect x="56" y="97" width="132" height="34" rx="2" fill="#658276"/><rect x="51" y="93" width="142" height="8" fill="#d1b685"/><path d="M75 93V78H93V93M79 75H90M135 93V80H149V93M153 93V80H167V93" fill="#d5c49d" stroke="#c3ab7d" stroke-width="2"/><circle cx="119" cy="69" r="10" fill="#bb9679"/><path d="M105 91V83Q119 72 133 83V93" fill="#c9ab70"/><path class="smoke" d="M82 69Q75 63 82 57M143 72Q138 66 144 60" fill="none" stroke="#c1cab1" stroke-width="2"/><text x="93" y="121" fill="#e8d5a4" font-size="12">চা ও আড্ডা</text>`;
return svg(ground+b)}
function save(){try{localStorage.setItem('dhaka-welcome',JSON.stringify({lang,startPlaceId:saved.startPlaceId||'mirpur12',reduced:document.body.classList.contains('reduce-motion')}))}catch{}}
let mainMenu;const vehicleIds=['bus','cng','biker','rickshaw'];const iconMap={bus:'assets/icon/bus.png',cng:'assets/icon/CNG.png',biker:'assets/icon/biker.png',rickshaw:'assets/icon/rickshaw.png'};function menuVehicles(){return vehicleIds.map(id=>{const r=roles.find(x=>x.id===id);const names={bus:['Bus','বাস'],cng:['CNG','সিএনজি'],biker:['Bike','বাইক'],rickshaw:['Rickshaw','রিকশা']};return{id:r.id,name:names[id],sub:r.sub,color:r.color,img:iconMap[id]}})}
const stallKinds=[{id:0,name:['Footpath Stall','ফুটপাতের দোকান'],color:'#b88649',img:'assets/icon/roadside_stall.png'},{id:1,name:['Tea Stall','চায়ের দোকান'],color:'#4a8c52',img:'assets/icon/tea_stall.png'},{id:2,name:['Fuchka Wala','ফুচকাওয়ালা'],color:'#984f55',img:'assets/icon/fuchka.png'}];
function menuStalls(){return stallKinds.map(k=>({variant:k.id,name:k.name,color:k.color,img:k.img}))}
function launchCharacter(roleId,extra={}){showAreaPicker({language:lang,selected:saved.startPlaceId||'mirpur12',onStart:({startPlaceId})=>{saved.startPlaceId=startPlaceId;save();mainMenu.hide();let starter;if(roleId==='bus')starter=startBusMission;else if(roleId==='cng')starter=startCngSession;else if(roleId==='rickshaw')starter=startRickshawMission;else if(roleId==='biker')starter=startBikerMission;else starter=startShopMission;if(starter)starter({language:lang,startPlaceId,onExit:()=>{render();mainMenu.show()},...extra})}})}
function setLang(next){lang=next;save();render();mainMenu?.relang()}
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>{const v=words[el.dataset.i];if(v){el.textContent=t(v);el.style.whiteSpace='pre-line'}});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('selected',b.dataset.lang===lang);b.setAttribute('aria-pressed',b.dataset.lang===lang)});save()}
const dialog=$('#dialog');function open(content){$('#dialog-content').innerHTML=content;dialog.showModal()}function close(){dialog.close()}$('.close').onclick=close;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function info(){open(`<div class="eyebrow">${lang==='en'?'WELCOME TO DHAKA':'ঢাকায় স্বাগতম'}</div><h2>${lang==='en'?'One city. Five stories.':'এক শহর। পাঁচ গল্প।'}</h2><p>${lang==='en'?'A playful traffic satire about the people who keep Dhaka moving. Choose your perspective, learn your role, and make a little room for everyone.':'ঢাকার প্রতিদিনের মানুষ ও রাস্তার গল্প নিয়ে মজার একটি গেম। চরিত্র বেছে নিন, নিয়ম জানুন এবং সবার জন্য একটু জায়গা রাখুন।'}</p><ol class="rule-list"><li>${lang==='en'?'Press Start Game to choose your perspective.':'স্টার্ট গেম প্রেস করে আপনার দৃষ্টিভঙ্গি বাছাই।'}</li><li>${lang==='en'?'Select a vehicle or stall from the menu.':'মেনু থেকে গাড়ি বা দোকান বাছাই।'}</li><li>${lang==='en'?'Change language or motion preferences at any time. Your choice stays on this browser.':'যেকোনো সময় ভাষা বা অ্যানিমেশনের সেটিংস বদলান। পছন্দ এই ব্রাউজারে সংরক্ষিত থাকে।'}</li></ol><p class="modal-note">${lang==='en'?'All five perspectives are available: Bus driver, CNG driver, Rickshaw puller, Biker, and Footpath shopkeeper. Bus driver includes Mission 1 in a continuous 3D city.':'সব পাঁচটি দৃষ্টিভঙ্গি উন্মুক্ত: বাস ড্রাইভার, সিএনজি চালক, রিকশাচালক, বাইকার এবং ফুটপাতের দোকানদার। বাস ড্রাইভারে থ্রিডি শহরে মিশন ১ রয়েছে।'}</p>`)}
$('#choose').onclick=()=>{mainMenu.show()};
if($('#choose-nav'))$('#choose-nav').onclick=()=>{mainMenu.show()};
function setNav(view){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{setNav(b.dataset.view);if(b.dataset.view==='how')info();else window.scrollTo({top:0,behavior:'smooth'})});
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;render()});
let audio,osc,gain;$('#sound').onclick=()=>{sound=!sound;try{if(sound){audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();osc=audio.createOscillator();gain=audio.createGain();osc.type='sine';osc.frequency.value=110;gain.gain.value=.018;osc.connect(gain);gain.connect(audio.destination);osc.start()}else{osc?.stop()}}catch{sound=false}$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('.sound-slash').style.display=sound?'none':'';toast(lang==='en'?(sound?'Ambient sound on':'Sound off'):(sound?'আবহাসিক শব্দ চালু':'শব্দ বন্ধ'))};
function loading(){const loader=$('#loader');if(!loader)return;loader.classList.remove('done');setTimeout(()=>loader.classList.add('done'),1500)}
$('#replay').onclick=loading;if(saved.reduced)document.body.classList.add('reduce-motion');
mainMenu=createMainMenu({lang:()=>lang,setLang,vehicles:menuVehicles(),stalls:menuStalls(),launchVehicle:id=>launchCharacter(id),launchStall:v=>{mainMenu.hide();startStallGame(v,{language:lang,onExit:()=>{render();mainMenu.show()}})}});
render();loading();
